    --椭圆轨迹
    StarImage1=DrawPicture:Create()
    StarImage1:Set({picture="book",width=30,height=30})
    StarImage2=DrawPicture:Create()
    StarImage2:Set({picture="book",width=30,height=30})
    center = {x=UI.ScreenSize().width/2,y=UI.ScreenSize().height/2}
    -- 初始化椭圆参数
    local centerX = center.x-15 -- 椭圆中心 x 坐标
    local centerY = center.y-75 -- 椭圆中心 y 坐标
    local radiusX = 50 -- 椭圆 x 轴半径
    local radiusY = 25 -- 椭圆 y 轴半径
    local speed = 3 -- 移动速度

    --每帧设置
    Framework.UIPlug.OnUpdate:Register(function(time)
        -- 根据速度更新角度
        if StarImage1 then
            local angle = UI.GetTime() * speed
            local imgX = centerX + math.cos(angle) * radiusX
            local imgY = centerY + math.sin(angle) * radiusY
            StarImage1:Set({x=imgX,y=imgY})
        end
        if StarImage2 then
            local angle = UI.GetTime() * speed
            local imgX = centerX + math.cos(angle+3.14) * radiusX
            local imgY = centerY + math.sin(angle+3.14) * radiusY
            StarImage2:Set({x=imgX,y=imgY})
        end
    end)
